package com.intermarche.backoffice.engine.printing;
import com.intermarche.backoffice.domain.printing.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.persistence.*;import jakarta.transaction.Transactional;import java.time.LocalDateTime;import java.util.*;
/** Each claim and outcome is durable; I/O runs outside its database transaction. */
@ApplicationScoped public class PrintQueue {
 @Inject EntityManager em;@Inject com.fasterxml.jackson.databind.ObjectMapper mapper;
 public record Work(Long id,int attempt,PrinterTransport.Destination destination,String payload){}
 private PrinterTransport.Destination destination(String value){try{return mapper.readValue(value,PrinterTransport.Destination.class);}catch(Exception e){throw new IllegalStateException("Configuration d’impression illisible",e);}}
 @Transactional public Work claim(){var now=DateTimeProvider.now();for(var stale:PrintJob.<PrintJob>list("state='SENDING' and sendingAt<?1",now.minusMinutes(2))){stale.state="UNKNOWN";stale.lastError="WORKER_INTERRUPTED";stale.revisionNumber++;for(var a:PrintAttempt.<PrintAttempt>list("job=?1 and state='SENDING'",stale)){a.state="UNKNOWN";a.errorCode="WORKER_INTERRUPTED";a.completedAt=now;}}
  var ids=em.createQuery("select j.id from PrintJob j where j.state='QUEUED' and (j.nextAttemptAt is null or j.nextAttemptAt<=?1) order by j.id",Long.class).setParameter(1,now).setMaxResults(1).getResultList();if(ids.isEmpty())return null;var job=em.find(PrintJob.class,ids.getFirst(),LockModeType.PESSIMISTIC_WRITE);if(!"QUEUED".equals(job.state))return null;
  if(!job.printer.enabled){job.state="FAILED";job.lastError="PRINTER_DISABLED";job.revisionNumber++;return null;}job.state="SENDING";job.sendingAt=now;job.attemptCount++;job.revisionNumber++;var attempt=new PrintAttempt();attempt.job=job;attempt.attemptNumber=job.attemptCount;attempt.state="SENDING";attempt.startedAt=now;attempt.persist();return new Work(job.id,job.attemptCount,destination(job.frozenDestination),job.frozenPayload);
 }
 @Transactional public void complete(Work work,String error,boolean uncertain){var job=em.find(PrintJob.class,work.id,LockModeType.PESSIMISTIC_WRITE);if(job==null||!"SENDING".equals(job.state)||job.attemptCount!=work.attempt)return;var now=DateTimeProvider.now();job.lastError=error;job.state=error==null?"SENT":uncertain?"UNKNOWN":job.attemptCount<3?"QUEUED":"FAILED";job.sentAt=error==null?now:null;job.nextAttemptAt="QUEUED".equals(job.state)?now.plusSeconds(10L*job.attemptCount):null;job.revisionNumber++;PrintAttempt attempt=PrintAttempt.find("job=?1 and attemptNumber=?2",job,work.attempt).firstResult();attempt.state=error==null?"SENT":uncertain?"UNKNOWN":"FAILED";attempt.errorCode=error;attempt.completedAt=now;}
}
